package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.widget.*;import android.text.InputType;import android.view.WindowManager;import org.json.*;
/** Password entry has no WebView bridge and never pre-fills saved credentials. */
public final class McpCredentialActivity extends Activity {
 boolean busy;
 public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);String name=getIntent().getStringExtra("name");try{McpSettings.validateName(name==null?"":name);}catch(Exception error){finish();return;}LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(30,70,30,30);TextView title=new TextView(this);title.setText(name+" · HTTP 凭据");body.addView(title);TextView help=new TextView(this);help.setText("仅保存在 Eva 本机私有配置文件（非加密配置），不会回传聊天网页。输入新 Bearer token 可替换旧值；取消不会修改。服务器请求会携带此凭据。");body.addView(help);EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setHint("Bearer token（无需 Bearer 前缀）");input.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO);body.addView(input);TextView status=new TextView(this);body.addView(status);Button save=new Button(this);save.setText("保存并重载");body.addView(save);Button clear=new Button(this);clear.setText("清除 Authorization 凭据");body.addView(clear);Button cancel=new Button(this);cancel.setText("取消");body.addView(cancel);cancel.setOnClickListener(v->{if(!busy)finish();});save.setOnClickListener(v->{String value=input.getText().toString().trim();if(value.isEmpty()){status.setText("请输入凭据；如需删除请使用清除按钮。");return;}input.setText("");write(name,value,status,save,clear);});clear.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("清除此连接的 Authorization 凭据？").setNegativeButton("取消",null).setPositiveButton("清除",(d,w)->write(name,"",status,save,clear)).show());setContentView(body);}
 void write(String name,String token,TextView status,Button save,Button clear){if(busy)return;busy=true;save.setEnabled(false);clear.setEnabled(false);status.setText("正在保存…");KernelHost host=getIntent().getBooleanExtra("api",false)?KernelHost.api(this):KernelHost.get(this);host.work.execute(()->{String result;try{host.ensureStarted();McpSettings.credential(host,name,token);host.emit(new JSONObject().put("method","android/mcpChanged").put("params",new JSONObject().put("name",name)));result="已保存并请求重载";}catch(Exception e){result="保存失败，请检查连接配置后重试";}final String message=result;runOnUiThread(()->{busy=false;save.setEnabled(true);clear.setEnabled(true);status.setText(message);if(message.startsWith("已保存"))finish();});});}
}
